package com.sumedha.commerce.user.controller; import com.sumedha.commerce.user.dto.request.*; import com.sumedha.commerce.user.dto.response.*; import com.sumedha.commerce.user.service.UserProfileService; import com.sumedha.commerce.common.core.api.ApiResponse; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/users/{authUserId}") public class UserProfileController {private final UserProfileService s;public UserProfileController(UserProfileService s){this.s=s;} @PostMapping("/profile") public ResponseEntity<ApiResponse<UserProfileResponse>> create(@PathVariable UUID authUserId,@Valid @RequestBody CreateProfileRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(s.create(authUserId,r)));}@GetMapping("/profile") public ApiResponse<UserProfileResponse> get(@PathVariable UUID authUserId){return ApiResponse.success(s.get(authUserId));}@PutMapping("/profile") public ApiResponse<UserProfileResponse> update(@PathVariable UUID authUserId,@Valid @RequestBody UpdateProfileRequest r){return ApiResponse.success(s.update(authUserId,r));}@PostMapping("/addresses") public ResponseEntity<ApiResponse<AddressResponse>> createAddress(@PathVariable UUID authUserId,@Valid @RequestBody CreateAddressRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(s.createAddress(authUserId,r)));}@GetMapping("/addresses") public ApiResponse<List<AddressResponse>> addresses(@PathVariable UUID authUserId){return ApiResponse.success(s.addresses(authUserId));}@GetMapping("/addresses/{addressId}") public ApiResponse<AddressResponse> address(@PathVariable UUID authUserId,@PathVariable UUID addressId){return ApiResponse.success(s.address(authUserId,addressId));}@PutMapping("/addresses/{addressId}") public ApiResponse<AddressResponse> updateAddress(@PathVariable UUID authUserId,@PathVariable UUID addressId,@Valid @RequestBody UpdateAddressRequest r){return ApiResponse.success(s.updateAddress(authUserId,addressId,r));}@DeleteMapping("/addresses/{addressId}") public ResponseEntity<Void> deleteAddress(@PathVariable UUID authUserId,@PathVariable UUID addressId){s.deleteAddress(authUserId,addressId);return ResponseEntity.noContent().build();}@GetMapping("/preferences") public ApiResponse<UserPreferencesResponse> preferences(@PathVariable UUID authUserId){return ApiResponse.success(s.preferences(authUserId));}@PutMapping("/preferences") public ApiResponse<UserPreferencesResponse> preferences(@PathVariable UUID authUserId,@Valid @RequestBody UpdatePreferencesRequest r){return ApiResponse.success(s.updatePreferences(authUserId,r));}}
